<template>
  <div v-if="eligible" class="ai-assistant">
    <button v-show="!ai.open" ref="launcher" type="button" class="ai-launcher" aria-label="打开鲜果AI客服" @click="show"><span aria-hidden="true">✦</span> 鲜果问答</button>
    <section v-show="ai.open" ref="panel" class="ai-panel" role="dialog" aria-label="鲜果AI客服" :aria-modal="mobile" @keydown="panelKey">
      <header class="ai-panel-header"><div class="ai-heading"><span class="ai-mark" aria-hidden="true">✦</span><div><h2>鲜果小助手</h2><p>{{ ai.buyer ? '你的水果咨询与订单助手' : '水果知识 · 商品咨询 · 礼盒推荐' }}</p></div></div><button type="button" class="ai-close" aria-label="关闭客服窗口" @click="close">×</button></header>
      <div class="ai-notice">回答可能使用在线模型，请勿输入手机号、详细地址或支付凭据。订单与退款以系统记录为准。</div>
      <div class="ai-toolbar"><button type="button" @click="ai.startNew">＋ 新对话</button><RouterLink v-if="ai.buyer" to="/account/ai-history" @click="close">历史记录</RouterLink><RouterLink v-else to="/login" @click="close">登录查看本人订单</RouterLink><span v-if="ai.context.productId">正在咨询所选商品</span><span v-else-if="ai.context.afterSaleId">已选择售后申请</span><span v-else-if="ai.context.orderId">已选择本人订单</span></div>
      <div ref="scroll" class="ai-message-list" @scroll="trackScroll">
        <div v-if="!ai.messages.length" class="ai-welcome"><div class="ai-welcome-fruit" aria-hidden="true">🍐</div><p class="eyebrow">你好，很高兴为你服务</p><h3>今天想了解什么水果？</h3><p>从储存方法到挑选礼盒，我可以帮你查资料。登录后还可以查询本人订单和售后。</p><div class="ai-starters"><button v-for="question in starters" :key="question" type="button" :disabled="ai.busy" @click="quick(question)">{{ question }} <span aria-hidden="true">↗</span></button></div></div>
        <article v-for="item in ai.messages" :key="item.id" class="ai-message" :class="item.role === 'USER' ? 'ai-user' : 'ai-answer'"><p class="ai-speaker">{{ item.role === 'USER' ? '你' : '鲜果小助手' }}<span v-if="item.mode === 'DEGRADED' || item.status === 'DEGRADED'" class="ai-mode">基础服务</span><span v-else-if="item.mode === 'BUSINESS'" class="ai-mode">系统查询</span><span v-else-if="item.mode === 'CATALOG'" class="ai-mode">商品资料</span></p><div class="ai-message-text">{{ item.content || (item.role === 'ASSISTANT' && isActive(item.status) ? '正在查询…' : '本次回答没有正文') }}</div>
          <p v-if="item.errorMessage" class="ai-result-note" role="status">{{ item.errorMessage }}</p>
          <div v-if="item.cards.length" class="ai-result-cards"><article v-for="card in item.cards" :key="card.type + card.id" class="ai-result-card"><img v-if="card.image" :src="imageUrl(card.image)" :alt="card.title" loading="lazy"><div><strong>{{ card.title }}</strong><p>{{ card.subtitle }}</p><b v-if="card.price">¥{{ price(card.price) }}</b><div class="ai-card-actions"><RouterLink v-if="trustedPath(card.path)" :to="card.path">查看详情</RouterLink><button type="button" :disabled="ai.busy" @click="selectCard(card)">继续咨询</button></div></div></article></div>
          <details v-if="item.sources.length" class="ai-sources"><summary>查看依据 · {{ item.sources.length }} 项</summary><div v-for="source in item.sources" :key="source.ordinal"><strong>[{{ source.ordinal }}] {{ source.title }}<small v-if="source.version"> · 版本 {{ source.version }}</small></strong><p>{{ source.excerpt }}</p><RouterLink v-if="source.path && trustedPath(source.path)" :to="source.path">查看商品或订单</RouterLink></div></details>
          <div v-if="item.role === 'ASSISTANT' && !isActive(item.status)" class="ai-answer-actions"><template v-if="item.status === 'COMPLETED' || item.status === 'DEGRADED'"><span>这条回答有帮助吗？</span><button type="button" :class="{ selected: item.helpful === true }" :aria-pressed="item.helpful === true" @click="ai.feedback(item, true)">有帮助</button><button type="button" :class="{ selected: item.helpful === false }" :aria-pressed="item.helpful === false" @click="ai.feedback(item, false)">没帮助</button></template><button v-if="item.requestId && item.status !== 'BLOCKED'" type="button" :disabled="ai.busy" @click="ai.retry(item.requestId)">重新回答</button></div>
        </article>
      </div>
      <button v-if="!atBottom && ai.messages.length" type="button" class="ai-scroll-latest" @click="latest">↓ 返回最新消息</button>
      <div class="ai-state" aria-live="polite">{{ ai.busy ? '正在准备或生成回答…' : ai.currentRequest?.status === 'CANCELLED' ? '回答已停止' : '' }}</div>
      <div v-if="ai.error" class="ai-error" role="alert">{{ ai.error }} <button type="button" @click="ai.recover">读取当前记录</button></div>
      <div class="ai-shortcuts"><button type="button" :disabled="ai.busy" @click="recommendOpen = !recommendOpen">挑选应季水果 / 礼盒</button><button type="button" :disabled="ai.busy" @click="quick('我的订单到哪了？')">查询订单</button><button type="button" :disabled="ai.busy" @click="quick('我的退款进度？')">退款进度</button></div>
      <form v-if="recommendOpen" class="ai-recommend-form" @submit.prevent="recommend"><label>总预算（元）<input v-model="requirements.budget" required type="number" min="0.01" max="99999999.99" step="0.01"></label><label>份数<input v-model.number="requirements.quantity" required type="number" min="1" max="999" step="1"></label><label>月份<select v-model.number="requirements.month"><option v-for="month in 12" :key="month" :value="month">{{ month }}月</option></select></label><label>用途<select v-model="requirements.useCase"><option value="">不限用途</option><option v-for="(label, value) in productUseCases" :key="value" :value="value">{{ label }}</option></select></label><label class="ai-gift-check"><input v-model="requirements.giftBox" type="checkbox">只看水果礼盒</label><button class="primary-button" :disabled="ai.busy">按条件推荐</button></form>
      <form class="ai-composer" @submit.prevent="submit"><label class="visually-hidden" for="ai-chat-input">输入咨询问题</label><textarea id="ai-chat-input" ref="input" v-model="draft" rows="2" maxlength="1000" placeholder="输入问题，Enter发送，Shift+Enter换行" :disabled="ai.loading" @keydown="inputKey" @compositionstart="composing = true" @compositionend="composing = false"></textarea><div><span>{{ draft.length }}/1000</span><button v-if="ai.busy" type="button" class="ai-send" @click="stop">停止回答</button><button v-else type="submit" class="ai-send" :disabled="!draft.trim()">发送 ↑</button></div></form>
      <footer class="ai-footer">{{ ai.buyer ? '历史记录保留180天，可在个人中心删除' : '访客记录仅保留24小时，登录后开启新的对话' }} · 关闭窗口会继续回答</footer>
    </section>
  </div>
</template>
<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { useAiStore } from '../stores/ai'
import { imageUrl, price, productUseCases } from '../api/catalog'
import type { AiCard, AiStatus } from '../api/ai'
const route = useRoute(), ai = useAiStore()
const eligible = computed(() => !route.path.startsWith('/admin') && route.path !== '/login')
const launcher = ref<HTMLButtonElement>(), input = ref<HTMLTextAreaElement>(), panel = ref<HTMLElement>(), scroll = ref<HTMLElement>()
const draft = ref(''), composing = ref(false), atBottom = ref(true), recommendOpen = ref(false), mobile = ref(false)
const requirements = reactive({ budget: '', quantity: 1, month: new Date().getMonth() + 1, giftBox: false, useCase: '' })
const starters = ['草莓怎么保存？', '可以退货吗？', '配送多久能到？', '帮我挑一份水果礼盒']
const isActive = (status: AiStatus | null) => status === 'ACCEPTED' || status === 'RUNNING'
const trustedPath = (path: string) => /^\/products\/\d+$/.test(path) || /^\/account\/orders\?orderId=\d+$/.test(path)
function latest() { if (scroll.value) scroll.value.scrollTop = scroll.value.scrollHeight; atBottom.value = true }
function trackScroll() { if (scroll.value) atBottom.value = scroll.value.scrollHeight - scroll.value.scrollTop - scroll.value.clientHeight < 60 }
async function show() { ai.open = true; await nextTick(); input.value?.focus() }
async function close() { ai.open = false; await nextTick(); launcher.value?.focus() }
async function submit() { if (ai.busy || !draft.value.trim()) return; const text = draft.value.trim(); await ai.send(text); if (!ai.error) draft.value = ''; await nextTick(); latest(); input.value?.focus() }
function quick(text: string) { if (text.includes('礼盒')) { recommendOpen.value = true; requirements.giftBox = true; return } draft.value = text; void submit() }
function inputKey(event: KeyboardEvent) { if (event.key === 'Enter' && !event.shiftKey && !event.isComposing && !composing.value) { event.preventDefault(); void submit() } }
function panelKey(event: KeyboardEvent) {
  if (event.key === 'Escape') { event.preventDefault(); void close() }
  if (event.key !== 'Tab' || !panel.value) return
  const elements = [...panel.value.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),summary')].filter(element => element.offsetParent !== null)
  const first = elements[0], last = elements.at(-1)
  if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus() }
  else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus() }
}
function selectCard(card: AiCard) { ai.openWithContext(card.context); void ai.send(card.type === 'ORDER' ? '查询这个订单状态与物流' : card.type === 'AFTER_SALE' ? '查询这个售后申请和退款进度' : '介绍一下这个商品的产地、口感和储存方法', card.context) }
function recommend() { recommendOpen.value = false; void ai.send('请按这些条件推荐应季水果', { budget: Number(requirements.budget), quantity: requirements.quantity, month: requirements.month, giftBox: requirements.giftBox ? true : undefined, useCase: requirements.useCase || undefined }) }
async function stop() { try { await ai.stop() } catch { /* The store displays the retryable error. */ } }
watch(() => ai.messages.map(item => item.content.length).join(':'), async () => { if (atBottom.value) { await nextTick(); latest() } })
watch(() => ai.open, async value => { if (value) { await nextTick(); input.value?.focus(); latest() } })
watch(eligible, value => { if (!value) { ai.open = false; void stop() } })
const media = window.matchMedia('(max-width: 600px)')
function resize() { mobile.value = media.matches }
onMounted(() => { resize(); media.addEventListener('change', resize) }); onUnmounted(() => media.removeEventListener('change', resize))
</script>
<style scoped>
.ai-launcher{position:fixed;right:24px;bottom:24px;z-index:90;display:flex;gap:10px;align-items:center;border:0;border-radius:28px;padding:15px 21px;background:#237a4c;color:white;box-shadow:0 6px 24px #205e4330;font:inherit;font-size:14px;cursor:pointer}.ai-launcher span{font-size:23px}.ai-panel{position:fixed;right:24px;bottom:24px;z-index:100;width:410px;max-width:calc(100vw - 32px);height:min(740px,calc(100dvh - 48px));display:flex;flex-direction:column;border:1px solid #dce5dc;border-radius:18px;background:#fff;box-shadow:0 16px 64px #203a3529;overflow:hidden}.ai-panel-header{display:flex;align-items:center;justify-content:space-between;padding:18px 18px 15px;background:#f1f7ef}.ai-heading{display:flex;gap:12px;align-items:center}.ai-mark{display:grid;place-items:center;width:42px;height:42px;border-radius:13px;background:#237a4c;color:#fff;font-size:26px}.ai-heading h2{margin:0;font-size:17px;color:#214830}.ai-heading p{margin:5px 0 0;font-size:11px;color:#677a6b}.ai-close{background:none;border:0;font-size:28px;color:#5c6c61;padding:0 3px;cursor:pointer}.ai-notice{padding:9px 16px;color:#7c785f;background:#fffbed;font-size:10px;line-height:1.6}.ai-toolbar{display:flex;flex-wrap:wrap;gap:13px;padding:10px 16px;border-bottom:1px solid #eaf0e8;font-size:11px;color:#738075}.ai-toolbar button,.ai-toolbar a,.ai-shortcuts button,.ai-card-actions button,.ai-card-actions a,.ai-answer-actions button,.ai-error button{border:0;background:none;padding:0;color:#2b7850;cursor:pointer;font:inherit}.ai-toolbar span{margin-left:auto}.ai-message-list{overflow-y:auto;flex:1;min-height:90px;padding:18px 16px;scrollbar-width:thin;overscroll-behavior:contain}.ai-welcome{text-align:center;padding:20px 10px}.ai-welcome-fruit{font-size:44px}.ai-welcome h3{font-size:20px;margin:9px 0 12px;color:#274f34}.ai-welcome p{font-size:12px;line-height:1.8;color:#758273}.ai-welcome .eyebrow{font-size:10px;letter-spacing:2px;margin-top:18px}.ai-starters{display:grid;gap:8px;margin-top:22px}.ai-starters button{display:flex;justify-content:space-between;padding:11px 12px;border:1px solid #e2e9dd;border-radius:8px;background:#fbfcf8;font:inherit;font-size:12px;color:#475d45;cursor:pointer}.ai-message{margin-bottom:22px;font-size:13px;line-height:1.75;overflow-wrap:anywhere}.ai-speaker{margin:0 0 7px;font-size:10px;color:#7b897b}.ai-user{margin-left:36px}.ai-user .ai-speaker{text-align:right}.ai-message-text{white-space:pre-wrap}.ai-user .ai-message-text{padding:11px 14px;background:#ecf5e8;border-radius:12px 12px 2px 12px;color:#294333}.ai-answer .ai-message-text{color:#354b3a}.ai-mode{margin-left:8px;padding:2px 5px;border-radius:4px;background:#f0f3ec;color:#798270}.ai-result-note{font-size:11px;color:#927541}.ai-result-card{display:flex;gap:11px;border:1px solid #e1e9dd;border-radius:9px;padding:10px;margin-top:10px;background:#fbfcf8}.ai-result-card img{width:62px;height:62px;border-radius:7px;object-fit:cover}.ai-result-card strong{font-size:12px}.ai-result-card p{font-size:11px;color:#829079;margin:3px 0}.ai-result-card b{color:#b6743b;font-size:12px}.ai-card-actions{display:flex;gap:17px;font-size:11px;margin-top:5px}.ai-sources{margin-top:13px;color:#73836b;font-size:11px}.ai-sources summary{cursor:pointer}.ai-sources>div{border-left:2px solid #d5e2cf;padding:7px 11px;margin-top:8px}.ai-sources p{line-height:1.6;color:#86917f;white-space:pre-wrap;margin:5px 0}.ai-sources a{color:#477d50}.ai-answer-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:12px;font-size:10px;color:#a1a79b}.ai-answer-actions .selected{font-weight:700;text-decoration:underline}.ai-answer-actions button:disabled,.ai-shortcuts button:disabled,.ai-card-actions button:disabled{opacity:.5;cursor:wait}.ai-state{font-size:10px;color:#74886d;padding:0 16px}.ai-error{background:#fff1ed;color:#98533c;font-size:11px;padding:8px 16px;line-height:1.7}.ai-error button{margin-left:8px}.ai-shortcuts{display:flex;gap:13px;padding:11px 16px;font-size:10px;flex-wrap:wrap;border-top:1px solid #eef2eb}.ai-composer{margin:0 12px;padding:10px 10px 7px;background:#fbfcf8;border:1px solid #d9e3d2;border-radius:11px}.ai-composer textarea{border:0;outline:0;resize:none;background:transparent;font:inherit;font-size:12px;color:#35543a;width:100%;min-height:40px;max-height:90px}.ai-composer:focus-within{border-color:#7aaa75}.ai-composer>div{display:flex;justify-content:space-between;align-items:center;font-size:9px;color:#a4ac9d}.ai-send{border:0;padding:7px 13px;background:#27754b;border-radius:7px;color:white;font:inherit;font-size:11px;cursor:pointer}.ai-send:disabled{opacity:.4;cursor:default}.ai-footer{padding:8px 10px 11px;text-align:center;font-size:9px;color:#a0a899;line-height:1.5}.ai-recommend-form{display:grid;grid-template-columns:1fr 1fr;gap:9px;padding:12px 16px;max-height:260px;overflow-y:auto;border-top:1px solid #e4ecde;background:#f8fbf5}.ai-recommend-form label{font-size:10px;display:grid;gap:4px;color:#718166}.ai-recommend-form input,.ai-recommend-form select{min-width:0;width:100%;font:inherit;background:white;border:1px solid #d5dfcc;border-radius:5px;padding:6px}.ai-recommend-form .ai-gift-check{display:flex;align-items:center}.ai-gift-check input{width:auto}.ai-scroll-latest{position:absolute;bottom:192px;right:20px;background:#fff;border:1px solid #d4e1ce;border-radius:15px;font:inherit;font-size:10px;color:#3c754d;padding:7px 11px;box-shadow:0 2px 8px #0001;cursor:pointer}@media(max-width:600px){.ai-launcher{right:16px;bottom:calc(18px + env(safe-area-inset-bottom));padding:12px 16px;font-size:12px}.ai-panel{inset:0;width:100%;max-width:none;height:100dvh;border-radius:0;border:0;padding-top:env(safe-area-inset-top);padding-bottom:env(safe-area-inset-bottom)}.ai-panel-header{padding:14px 17px}.ai-message-list{padding:18px}.ai-composer textarea{font-size:16px}.ai-footer{font-size:9px}}
</style>
